        "text": "Каутса учил: рвота о двух-трёх позывах — малая мера, о четырёх-пяти — средняя, о шести-семи — высшая. Парашарья же говорил, что должная мера зависит от телосложения больного — истощён он, средних сил или крепок. А многие иные учителя полагали, что мера рвотного средства определяется самим заболеванием."
