        "text": "Здесь приводятся такие стихи. Кто в мире не знает, что при возникшей у ребёнка болезни довольно очистить (шодхана) одну только кормилицу — и этого достаточно для благополучия младенца? Но у самого ребёнка в теле уже накопились доши прежде; и пока их не удалили, как может утихнуть его недуг? Не устранённая заранее (эта причина) в будущем лишь навредит, не давая крепнуть его телу (природе). Когда же врач надлежащим образом очищает обоих — и кормилицу, и самого ребёнка, — здоровье возвращается быстро, и запечатлевается в младенце твёрдо, точно черта, высеченная на камне. Кормилица есть вместилище дош ребёнка, подобно тому как горы — исток рек: (текст повреждён) — пришедшая (через неё, испорченная) доша мучает младенца. Поэтому, покуда не очищены оба — и мать, и дитя, — об умиротворении недуга не может быть и речи; таково верное понимание. А тот младенец, который, снова и снова напившись молока, сам срыгивает его, — того никогда не тревожат ни божественные, ни человеческие болезни. Через грудное молоко доша переходит к ребёнку, вызывая у детей язвы во рту, а у кормилицы — лихорадку. Поэтому лекарство младенцу следует давать именно через сосок (то есть вместе с молоком матери), пусть даже принудительно."
