        "text": "Далее: от избыточного насыщения (бримхана), избыточной сухости, чрезмерного истощения, избытка мяса и жира; оттого, что лекарство взято в слишком малой дозе, либо слишком густо, слишком жидко, слишком горячо, слишком холодно, слишком сладко, слишком остро, слишком солоно, слишком вяжуще, слишком кисло, слишком щёлочно, либо отвратительно по виду, вкусу и запаху (фрагмент повреждён); оттого, что принявший лекарство человек засыпает, дремлет или отвлекается мыслью после приёма; оттого, что он подвергается холодному ветру, холодному помещению, холодной воде, холодной одежде; оттого, что пренебрегает обувью и огнём (теплом); оттого, что сдерживает позывы (далее фрагмент повреждён), — возникают неправильное (дурное) и избыточное действие рвотных и слабительных средств. Их признаками служат такие осложнения: вздутие живота, насморк, задержка (стула), стеснение в сердце, колющая боль, режущая боль, рвота, спазм головы, дизентерийные тенезмы, икота, одышка, кашель, сухость нёба и горла (фрагмент повреждён), обильное слюноотделение, лихорадка от подавленного (не вышедшего) позыва, уныние, нарушение выделений из телесных каналов — таковы осложнения, указывающие на неправильное применение (дурьогу)."
