        "text": "От сдерживания позывов обостряются все три доши, происходит небольшая потеря жизненной крови, безумие и головокружение. Даже у человека с мягким кишечником, получившего должное умащение и потогонное очищение, если ему дают слишком много лекарства, оно приводит к потере жизненной крови (фрагмент повреждён) — усиливает (свои неблагоприятные) качества и обостряет Вату; а обострившаяся Вата вызывает бред, безумие, икоту, одышку, кашель, сухость нёба, жажду, боль, глухоту, потерю речи, порчу семени, помутнение зрения (тимиру) и расстройство менструаций (пушпа-упагхата)."
