        "text": "И в том, и в другом случае (то есть при атийоге и при айоге) показано очищение или же Нируха-васти. Это устраняет режущую боль, вздутие, истечения, урчание, колики, повышенную сонливость и глубокое уныние. Больному дают пить (с этой целью) топлёное масло, сваренное с трифалой, читраком, урупугой (кастором), данти и шьямой — по надлежащему применению; либо же дают через басти масло, топлёное масло или молоко, сваренные с укрепляющими жизнь (дживания) травами, для успокоения задержки, урчания, боли, истечений, тенезмов и Ваты (фрагмент повреждён); либо — молоко, сваренное с трифалой, кашмарьей, виноградом и корой гандхапашаны, что рекомендуется в качестве басти при задержке и истечениях. Для Анувасана-басти рекомендуется гандхарва-тайла (касторовое масло), успокаивающее все недуги Ваты, приготовленное с отваром гандхарвы; либо масло, сваренное с пастой из хинга, дарухаридры, девадару, недозрелого билвы, патхьи и путики на кислой канджи, — такое масло, применённое так же для Анувасана-васти, по преданию, устраняет все осложнения; оно и называется гандхарва-тайлой."
