        "text": "Здесь приводятся такие стихи. И в том, и в другом случае (то есть при атийоге и айоге) следует пить холодный вяжущий отвар (фрагмент повреждён). Тело больного, вместе с головой, поскорее умащают топлёным маслом и обливают весьма холодной водой; стопы же омывают холодной водой (фрагмент повреждён). Катфалу, лотос, явасу, мочарасу, кешару, ушир и мангиштху, тщательно растёртые с холодной водой либо с соком холодных млечных деревьев, наносят в виде обмазки от головы до стоп (фрагмент повреждён); а также прохладной постелью, прохладным сиденьем, прохладным питьём и прохладной пищей. Так же, как оберегают ещё не занявшуюся часть загоревшегося дома, мудрый врач должен как можно скорее унять этот (избыточный) недуг."
