        "text": "Признаки Ама-джвары («сырой», незрелой лихорадки): запор, отсутствие аппетита, жажда, обморочность, ломота в теле, головная боль, бред, вялость, тошнота, сонливое оцепенение (тандра), жар, утомляемость, головокружение, обильное мочеиспускание, слабость, неперевариваемость кала, движение дош вверх (утклеша) и тяжесть в области желудка и кишечника — таковы признаки Амаджвары."
