        "text": "Когда дошй успокоены и во всех вместилищах отработанных веществ (мала) устранены препятствия к их естественному отправлению, в тканях тела (дхату) рождается ясность (прасада). Поэтому, когда дошй, ткани и отработанные вещества пребывают каждый в своей надлежащей деятельности, у людей возникает здоровье; когда же это нарушено — возникает нездоровье."
