        "sanskrit": "अतिद्रुतं हि भुञ्जानो नाहारस्थितिमाप्नुयात्‌ । भोज्यानुपूर्वीं नो वेत्ति न चान्नरससम्पदम्‌ ।।२५।। नातिद्रुताशी तत्सर्वमनूनं प्रतिपद्यते । प्रसादमिन्द्रियाणां च तथा वातानुलोमताम्‌ ।।२६।।",
        "text": "12. Кто ест чересчур поспешно, тот не даёт пище должным образом улечься, не различает порядка блюд и не постигает всего богатства вкусов пищи. Тот же, кто не спешит с едой, в полной мере обретает всё это, а также ясность органов чувств и правильное, естественное направление движения Ваты."
